class FortranConvert:
    """Convert Fortran-formatted float: e.g., "1.23F4" means 1.23 * 10**4"""
    def __call__(self, string, match):
        import re as _re
        m = _re.match(r'([-+]?\d*\.?\d+)[eEfF]([-+]?\d+)', string)
        if m:
            mantissa = float(m.group(1))
            exponent = int(m.group(2))
            return mantissa * (10 ** exponent)
        return float(string)


class IdentityConvert:
    """Identity conversion - return string as-is."""
    def __call__(self, string, match):
        return string


